// ---------- constantes ----------
const STATUS_PRODUCAO = [
  "Agendado",
  "Em edição",
  "Entregue ao cliente",
  "Aprovado",
  "Alteração",
];

const STATUS_COR = {
  "Agendado": "#8A7F6E",
  "Em edição": "#B9862E",
  "Entregue ao cliente": "#3E6B8A",
  "Aprovado": "#3F4F3A",
  "Alteração": "#A83B2E",
};

const STATUS_CONCLUIDO = "Aprovado"; // status que conta como "finalizado" em cálculos e no Quadro

// produções do tipo "Vídeo" ou "Reels" não geram fotos — não faz sentido mostrar status de foto pra elas
const temFotoProducao = (p) => p.tipo !== "Vídeo" && p.tipo !== "Reels";

// uma produção só conta como concluída de verdade quando fotos (se houver) E vídeo (se houver) estão aprovados
const producaoConcluida = (p) =>
  (!temFotoProducao(p) || p.status === STATUS_CONCLUIDO) && (!p.temVideo || p.statusVideo === STATUS_CONCLUIDO);

// status "principal" pra mostrar num badge único — foto normalmente, ou vídeo quando a produção não tem foto
const statusPrincipal = (p) => (temFotoProducao(p) ? p.status : p.statusVideo || "Agendado");

// data em que a produção ficou de fato pronta (a mais tardia entre foto aprovada e vídeo aprovado)
function dataConclusao(p) {
  if (!producaoConcluida(p)) return null;
  const historico = p.historico || [];
  const entradaFoto = [...historico].reverse().find((h) => h.status === STATUS_CONCLUIDO && h.campo !== "video");
  if (!entradaFoto && temFotoProducao(p)) return null;
  let em = entradaFoto ? entradaFoto.em : null;
  if (p.temVideo) {
    const entradaVideo = [...historico].reverse().find((h) => h.status === STATUS_CONCLUIDO && h.campo === "video");
    if (entradaVideo && (!em || entradaVideo.em > em)) em = entradaVideo.em;
  }
  return em ? new Date(em).toISOString().slice(0, 10) : null;
}

// descreve o status real de uma produção, deixando claro o que ainda falta quando ela tem foto e vídeo
function statusDescritivo(p) {
  if (!temFotoProducao(p)) return p.statusVideo || "Agendado";
  if (!p.temVideo) return p.status;
  if (producaoConcluida(p)) return p.status;
  const partes = [];
  if (p.status !== STATUS_CONCLUIDO) partes.push(`Foto: ${p.status}`);
  if ((p.statusVideo || "Agendado") !== STATUS_CONCLUIDO) partes.push(`Vídeo: ${p.statusVideo || "Agendado"}`);
  return partes.join(" · ") || p.status;
}

const STATUS_PAGAMENTO = ["Em aberto", "Pago", "Parcialmente pago", "Cancelado"];

// ---------- Produtora (eventos) ----------
const COR_PRODUTORA = "#33475B";
const COR_PRODUTORA_CLARA = "#4A6478";
const STATUS_EVENTO = ["Planejado", "Pagamento em aberto", "Concluído"];
const STATUS_EVENTO_COR = { "Planejado": "#B9862E", "Pagamento em aberto": "#33475B", "Concluído": "#566B4F" };
const CATEGORIAS_DESPESA_EVENTO = ["Transporte", "Hospedagem", "Alimentação", "Outras"];
const FUNCOES_EVENTO = ["Fotógrafo", "Filmmaker", "Editor de foto", "Editor de vídeo", "Storymaker", "Produção", "Assistente", "Outro"];
const btnPrimarioProdutora = { background: "#33475B", color: "#FBF4E9", border: "none", padding: "9px 18px", borderRadius: 999, fontSize: 14, fontWeight: 600, cursor: "pointer", marginTop: 6 };
const totalCaches = (ev) => (ev.freelancersEscalados || []).reduce((s, f) => s + (Number(f.cache) || 0), 0);
const totalDespesasEvento = (ev) => (ev.despesas || []).reduce((s, d) => s + (Number(d.valor) || 0), 0);
const totalRecebidoEvento = (ev) => (ev.parcelas || []).filter((p) => p.recebida).reduce((s, p) => s + (Number(p.valor) || 0), 0);
const PERCENTUAL_NOTA_FISCAL = 0.07;
const valorNotaFiscalCalculado = (ev) => (ev.emiteNotaFiscal ? Math.round((Number(ev.valorFaturado) || 0) * PERCENTUAL_NOTA_FISCAL * 100) / 100 : 0);
const lucroEvento = (ev) => (Number(ev.valorFaturado) || 0) - totalCaches(ev) - totalDespesasEvento(ev) - valorNotaFiscalCalculado(ev);

const PRECOS_PADRAO = { look: 40, lookbook: 150, video: 50, prato: 50, fotoCorporativa: 50 };

const uid = () => Math.random().toString(36).slice(2, 10);
const hoje = () => new Date().toISOString().slice(0, 10);
const fmtBRL = (v) =>
  (v || 0).toLocaleString("pt-BR", { style: "currency", currency: "BRL" });
const fmtData = (iso) => {
  if (!iso) return "—";
  const [y, m, d] = iso.split("-");
  return `${d}/${m}/${y}`;
};
const fmtDataHora = (ts) => {
  if (!ts) return "—";
  const d = new Date(ts);
  const pad = (n) => String(n).padStart(2, "0");
  return `${pad(d.getDate())}/${pad(d.getMonth() + 1)} às ${pad(d.getHours())}:${pad(d.getMinutes())}`;
};
const MESES_PT = ["janeiro", "fevereiro", "março", "abril", "maio", "junho", "julho", "agosto", "setembro", "outubro", "novembro", "dezembro"];
const fmtMesAno = (ts) => {
  if (!ts) return null;
  const d = new Date(ts);
  return `${MESES_PT[d.getMonth()]}/${d.getFullYear()}`;
};
const diasEntre = (a, b) => Math.floor((new Date(b) - new Date(a)) / 86400000);

function pastaDrive(p) {
  const [y] = (p.data || hoje()).split("-");
  return `Clientes / ${p.cliente || "—"} / ${y} / ${fmtData(p.data)}`;
}

function totalProducao(p, precos) {
  let bruto;
  if (p.valorFixo !== undefined && p.valorFixo !== null && p.valorFixo !== "") {
    bruto = Number(p.valorFixo) || 0;
  } else {
    bruto =
      (Number(p.looks) || 0) * precos.look +
      (Number(p.lookbooks) || 0) * precos.lookbook +
      (Number(p.videos) || 0) * precos.video +
      (Number(p.qtdPrato) || 0) * (precos.prato || 0) +
      (Number(p.qtdFotoCorporativa) || 0) * (precos.fotoCorporativa || 0);
  }
  const desconto = Number(p.desconto) || 0;
  return Math.max(0, bruto - desconto);
}

// retorna a lista de mensalidades de um cliente, com fallback pro formato antigo (valorMensal único)
function mensalidadesDoCliente(c) {
  if (c.mensalidades && c.mensalidades.length) return c.mensalidades;
  if (Number(c.valorMensal) > 0) {
    return [{ mes: hoje().slice(0, 7), valor: c.valorMensal, pago: c.statusRecorrente === "Pago" }];
  }
  return [];
}

function redimensionarFoto(arquivo, tamanhoMax = 320, qualidade = 0.75) {
  return new Promise((resolve, reject) => {
    const leitor = new FileReader();
    leitor.onload = (e) => {
      const img = new window.Image();
      img.onload = () => {
        let w = img.width;
        let h = img.height;
        if (w > h && w > tamanhoMax) {
          h = Math.round(h * (tamanhoMax / w));
          w = tamanhoMax;
        } else if (h >= w && h > tamanhoMax) {
          w = Math.round(w * (tamanhoMax / h));
          h = tamanhoMax;
        }
        const canvas = document.createElement("canvas");
        canvas.width = w;
        canvas.height = h;
        canvas.getContext("2d").drawImage(img, 0, 0, w, h);
        resolve(canvas.toDataURL("image/jpeg", qualidade));
      };
      img.onerror = reject;
      img.src = e.target.result;
    };
    leitor.onerror = reject;
    leitor.readAsDataURL(arquivo);
  });
}

function linkGoogleAgenda(p) {
  const pad = (n) => String(n).padStart(2, "0");
  const fmt = (d) => `${d.getFullYear()}${pad(d.getMonth() + 1)}${pad(d.getDate())}T${pad(d.getHours())}${pad(d.getMinutes())}00`;
  const inicio = new Date(`${p.data || hoje()}T${p.horario || "09:00"}:00`);
  const fim = new Date(inicio.getTime() + 2 * 60 * 60 * 1000); // duração padrão: 2h

  const responsaveis = [
    p.fotografo && `Fotógrafo: ${p.fotografo}`,
    p.filmmaker && `Filmmaker: ${p.filmmaker}`,
    p.editor && `Editor: ${p.editor}`,
    p.storymaker && `Storymaker: ${p.storymaker}`,
  ].filter(Boolean);

  const details = [
    p.tipo && `Tipo: ${p.tipo}`,
    p.modelo && `Modelo: ${p.modelo}`,
    p.cenario && `Cenário: ${p.cenario}`,
    ...responsaveis,
    p.prazo && `Prazo de entrega: ${fmtData(p.prazo)}`,
    p.referencias && `Referências: ${p.referencias}`,
    p.observacoes && `Observações: ${p.observacoes}`,
  ]
    .filter(Boolean)
    .join("\n");

  const params = new URLSearchParams({
    action: "TEMPLATE",
    text: `${p.tipo || "Ensaio"} — ${p.cliente || "Studio Aroeira"}`,
    dates: `${fmt(inicio)}/${fmt(fim)}`,
    details,
    location: p.localizacao || "",
    ctz: "America/Recife",
  });

  return `https://calendar.google.com/calendar/render?${params.toString()}`;
}

